                      `created_at`, `updated_at`)
VALUES (1, 1, 1, '초콜릿 퍼지', '초콜릿과 누텔라 두 가지 재료만으로 만드는 꾸덕한 식감의 초간단 디저트입니다.', 2, 70, 'ETC', 'DESSERT',
