        '2026-02-16 03:32:12.934944'),
       (2, 1, 2, '김치볶음밥', '마요네즈를 넣어 고소함과 감칠맛을 살린 김치볶음밥 황금레시피입니다.', 1, 15, 'KOREAN', 'MAIN',
        'BEGINNER', 'IMPORT', 0, NULL, 1, '2026-02-16 03:32:53.346510',
        '2026-02-16 03:32:53.346510'),
       (3, 1, 3, '등갈비찜', '달콤하고 짭짤한 양념이 뼈까지 쏙 밴 부드러운 식감의 일품 등갈비 요리입니다.', 2, 90, 'KOREAN', 'MAIN',
