        'BEGINNER', 'IMPORT', 0, NULL, 1, '2026-02-16 03:35:11.542859',
        '2026-02-16 03:35:11.542859'),
       (5, 1, 5, '크림 치킨 스튜', '고소한 우유와 생크림 소스에 노릇하게 구운 닭다리살을 넣어 만든 부드러운 스튜입니다.', 2, 30, 'WESTERN',
        'MAIN', 'BEGINNER', 'IMPORT', 0, NULL, 1, '2026-02-16 03:35:30.096246',
        '2026-02-16 03:35:30.096246'),
       (6, 1, 6, '오무라이스', '베이컨과 양파를 넣어 고소하게 볶은 밥 위에 부드러운 계란을 얹어 만드는 간단한 한 그릇 요리입니다.', 1, 15,
        'FUSION', 'MAIN', 'BEGINNER', 'IMPORT', 0, NULL, 1, '2026-02-16 03:35:42.667679',
        '2026-02-16 03:35:42.667679'),
