        'BEGINNER', 'IMPORT', 0, NULL, 1, '2026-02-16 03:36:04.675273',
        '2026-02-16 03:36:04.675273'),
       (8, 1, 8, '계란국', '코인 육수를 활용하여 누구나 쉽고 빠르게 끓일 수 있는 담백하고 고소한 계란국입니다.', 2, 10, 'KOREAN',
        'SIDE_DISH', 'BEGINNER', 'IMPORT', 0, NULL, 1, '2026-02-16 03:36:15.045484',
        '2026-02-16 03:36:15.045484'),
       (9, 1, 9, '새우 채소 구이', '배우 이시영의 다이어트 식단으로 유명하며, 새우와 구운 채소에 특제 소스를 곁들여 포만감이 높은 건강식입니다.', 1, 15,
