        '2026-02-16 03:37:13.840556'),
       (13, 1, 13, '소갈비찜', '일반 냄비로도 고기가 부드럽게 쏙 빠지는 달콤 짭짤한 소갈비찜 레시피입니다.', 4, 160, 'KOREAN', 'MAIN',
        'INTERMEDIATE', 'IMPORT', 0, NULL, 1, '2026-02-16 03:37:32.161596',
        '2026-02-16 03:37:32.161596'),
       (14, 1, 14, '새우 원팬 파스타', '설거지 걱정 없이 팬 하나로 간편하게 완성하는 감칠맛 가득한 새우 파스타입니다.', 1, 15, 'WESTERN',
