       (15, 1, 15, '떡갈비', '소고기와 돼지고기를 섞어 풍부한 육즙과 쫀득한 식감을 살린 정통 떡갈비 레시피입니다.', 4, 150, 'KOREAN',
        'MAIN', 'BEGINNER', 'IMPORT', 0, NULL, 1, '2026-02-16 03:38:10.446763',
        '2026-02-16 03:38:10.446763'),
       (16, 1, 16, '안성재 계란김밥', '버터와 카레가루를 더해 풍미를 살린 안성재 셰프 스타일의 고소하고 담백한 계란김밥입니다.', 2, 20, 'KOREAN',
        'MAIN', 'BEGINNER', 'IMPORT', 0, NULL, 1, '2026-02-16 03:38:21.985111',
        '2026-02-16 03:38:21.985111'),
       (17, 1, 17, '브로콜리 참깨 무침', '고소한 참깨 드레싱과 아삭한 브로콜리가 어우러진 영양 가득한 건강 반찬입니다.', 2, 15, 'KOREAN',
        'SIDE_DISH', 'BEGINNER', 'IMPORT', 0, NULL, 1, '2026-02-16 03:38:48.065091',
        '2026-02-16 03:38:48.065091'),
       (18, 1, 18, '햄치즈 토스트', '달콤한 키위 소스가 매력적인 이삭토스트 스타일의 햄치즈 토스트입니다.', 1, 10, 'KOREAN', 'SNACK',
        'BEGINNER', 'IMPORT', 0, NULL, 1, '2026-02-16 03:39:16.734787',
        '2026-02-16 03:39:16.734787'),
       (19, 1, 19, '원팬 크림 파스타', '팬 하나로 설거지 걱정 없이 간편하게 완성하는 고소하고 꾸덕한 크림 파스타입니다.', 1, 15, 'WESTERN',
        'MAIN', 'BEGINNER', 'IMPORT', 0, NULL, 1, '2026-02-16 03:39:29.423057',
        '2026-02-16 03:39:29.423057'),
