        'WESTERN', 'MAIN', 'BEGINNER', 'IMPORT', 0, NULL, 1, '2026-02-16 03:39:57.782659',
        '2026-02-16 03:39:57.782659'),
       (21, 1, 21, '닭도리탕', '매콤하고 진한 양념이 닭고기에 쏙 배어든 닭도리탕입니다. 닭을 미리 데쳐내어 잡내 없이 깔끔한 맛을 냅니다.', 2, 30,
        'KOREAN', 'MAIN', 'BEGINNER', 'IMPORT', 0, NULL, 1, '2026-02-16 03:40:09.233498',
        '2026-02-16 03:40:09.233498'),
       (22, 1, 22, '토마토 원팬 파스타', '팬 하나로 간편하게 조리하여 설거지를 줄인 새우 베이컨 토마토 파스타입니다.', 1, 25, 'WESTERN',
