VALUES (1, 1, 1, 1, 'https://youtube.com/shorts/PRXECGqzcec?si=o1hFfQ8KqqhT645b', 'YOUTUBE',
        '{\n    \"title\": \"초콜릿 퍼지\",\n    \"description\": \"초콜릿과 누텔라 두 가지 재료만으로 만드는 꾸덕한 식감의 초간단 디저트입니다.\",\n    \"servingSize\": 2,\n    \"cookingTime\": 70,\n    \"cuisineType\": \"ETC\",\n    \"mealType\": \"DESSERT\",\n    \"difficulty\": \"BEGINNER\",\n    \"ingredients\": [\n        {\n            \"name\": \"초콜릿\",\n            \"amount\": \"200\",\n            \"unit\": \"g\"\n        },\n        {\n            \"name\": \"누텔라\",\n            \"amount\": \"200\",\n            \"unit\": \"g\"\n        }\n    ],\n    \"steps\": [\n        {\n            \"stepNumber\": 1,\n            \"description\": \"좋아하는 판 초콜릿을 조각내어 전자레인지에 넣고 녹여줍니다.\"\n        },\n        {\n            \"stepNumber\": 2,\n            \"description\": \"녹인 초콜릿에 누텔라를 듬뿍 넣고 서로 잘 섞이도록 저어줍니다.\"\n        },\n        {\n            \"stepNumber\": 3,\n            \"description\": \"용기에 종이호일을 깔고 준비한 초콜릿 반죽을 평평하게 부어줍니다.\"\n        },\n        {\n            \"stepNumber\": 4,\n            \"description\": \"냉장고에 넣고 약 1시간 동안 굳혀주면 완성입니다.\"\n        }\n    ],\n    \"tags\": [\n        \"디저트\",\n        \"홈베이킹\",\n        \"간편레시피\",\n        \"스위츠\"\n    ]\n}',
        NULL, NULL, 'COMPLETED', '2026-02-16 03:31:50.875898', '2026-02-16 03:32:13.054700'),
       (2, 1, 2, 2, 'https://youtube.com/shorts/ldsIYEb1t5o?si=BAwboyUg5WPCUhAw', 'YOUTUBE',
        '{\n    \"title\": \"김치볶음밥\",\n    \"description\": \"마요네즈를 넣어 고소함과 감칠맛을 살린 김치볶음밥 황금레시피입니다.\",\n    \"servingSize\": 1,\n    \"cookingTime\": 15,\n    \"cuisineType\": \"KOREAN\",\n    \"mealType\": \"MAIN\",\n    \"difficulty\": \"BEGINNER\",\n    \"ingredients\": [\n        {\"name\": \"김치\", \"amount\": \"1\", \"unit\": \"컵\"},\n        {\"name\": \"대파\", \"amount\": \"0.5\", \"unit\": \"대\"},\n        {\"name\": \"스팸\", \"amount\": \"100\", \"unit\": \"g\"},\n        {\"name\": \"설탕\", \"amount\": \"1\", \"unit\": \"큰술\"},\n        {\"name\": \"고춧가루\", \"amount\": \"1\", \"unit\": \"큰술\"},\n        {\"name\": \"참기름\", \"amount\": \"1\", \"unit\": \"큰술\"},\n        {\"name\": \"마요네즈\", \"amount\": \"1\", \"unit\": \"큰술\"},\n        {\"name\": \"식용유\", \"amount\": \"2\", \"unit\": \"큰술\"},\n        {\"name\": \"밥\", \"amount\": \"1\", \"unit\": \"공기\"},\n        {\"name\": \"계란\", \"amount\": \"2\", \"unit\": \"개\"},\n        {\"name\": \"김가루\", \"amount\": \"1\", \"unit\": \"큰술\"},\n        {\"name\": \"통깨\", \"amount\": \"0.5\", \"unit\": \"큰술\"}\n    ],\n    \"steps\": [\n        {\"stepNumber\": 1, \"description\": \"김치, 대파, 스팸을 먹기 좋은 크기로 잘게 썰어 준비합니다.\"},\n        {\"stepNumber\": 2, \"description\": \"손질한 재료에 설탕, 고춧가루, 참기름, 마요네즈를 넣고 골고루 버무려 양념합니다.\"},\n        {\"stepNumber\": 3, \"description\": \"팬에 식용유를 두르고 양념한 김치 재료를 넣고 볶습니다.\"},\n        {\"stepNumber\": 4, \"description\": \"김치전처럼 팬에 꾹꾹 눌러 펼쳤다가 다시 볶는 과정을 2~3번 반복하여 노릇하게 익힙니다.\"},\n        {\"stepNumber\": 5, \"description\": \"밥을 넣고 양념이 고루 섞이도록 충분히 볶아줍니다.\"},\n        {\"stepNumber\": 6, \"description\": \"계란 후라이를 만들어 볶음밥 위에 올리고 김가루와 통깨를 뿌려 완성합니다.\"}\n    ],\n    \"tags\": [\"한식\", \"볶음밥\", \"집밥\", \"간단요리\"]\n}',
        NULL, NULL, 'COMPLETED', '2026-02-16 03:32:26.064636', '2026-02-16 03:32:53.502086'),
       (3, 1, 3, 3, 'https://youtube.com/shorts/XdpgNElrt3Q?si=7GW_GJjHvz9Z5Soy', 'YOUTUBE',
        '{\n  \"title\": \"등갈비찜\",\n  \"description\": \"달콤하고 짭짤한 양념이 뼈까지 쏙 밴 부드러운 식감의 일품 등갈비 요리입니다.\",\n  \"servingSize\": 2,\n  \"cookingTime\": 90,\n  \"cuisineType\": \"KOREAN\",\n  \"mealType\": \"MAIN\",\n  \"difficulty\": \"INTERMEDIATE\",\n  \"ingredients\": [\n    {\n      \"name\": \"등갈비\",\n      \"amount\": \"1\",\n      \"unit\": \"kg\"\n    },\n    {\n      \"name\": \"물\",\n      \"amount\": \"1.5\",\n      \"unit\": \"L\"\n    },\n    {\n      \"name\": \"설탕\",\n      \"amount\": \"2\",\n      \"unit\": \"큰술\"\n    },\n    {\n      \"name\": \"갈아만든배\",\n      \"amount\": \"0.67\",\n      \"unit\": \"컵\"\n    },\n    {\n      \"name\": \"양파\",\n      \"amount\": \"0.5\",\n      \"unit\": \"개\"\n    },\n    {\n      \"name\": \"대파\",\n      \"amount\": \"20\",\n      \"unit\": \"cm\"\n    },\n    {\n      \"name\": \"진간장\",\n      \"amount\": \"4\",\n      \"unit\": \"큰술\"\n    },\n    {\n      \"name\": \"굴소스\",\n      \"amount\": \"1\",\n      \"unit\": \"큰술\"\n    },\n    {\n      \"name\": \"맛술\",\n      \"amount\": \"2\",\n      \"unit\": \"큰술\"\n    },\n    {\n      \"name\": \"물엿\",\n      \"amount\": \"3\",\n      \"unit\": \"큰술\"\n    },\n    {\n      \"name\": \"매실액\",\n      \"amount\": \"1\",\n      \"unit\": \"큰술\"\n    },\n    {\n      \"name\": \"다진 마늘\",\n      \"amount\": \"2\",\n      \"unit\": \"큰술\"\n    },\n    {\n      \"name\": \"생강가루\",\n      \"amount\": \"0.5\",\n      \"unit\": \"작은술\"\n    },\n    {\n      \"name\": \"후춧가루\",\n      \"amount\": \"0.33\",\n      \"unit\": \"작은술\"\n    },\n    {\n      \"name\": \"월계수잎\",\n      \"amount\": \"2\",\n      \"unit\": \"장\"\n    },\n    {\n      \"name\": \"통후추\",\n      \"amount\": \"1\",\n      \"unit\": \"작은술\"\n    },\n    {\n      \"name\": \"소주\",\n      \"amount\": \"1\",\n      \"unit\": \"잔\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": 1,\n      \"description\": \"물 1L에 설탕 1큰술을 녹인 뒤 등갈비를 넣고 30분간 핏물을 빼줍니다.\"\n    },\n    {\n      \"stepNumber\": 2,\n      \"description\": \"갈아만든배 2/3컵과 양파 반 개는 믹서기로 갈고, 대파 흰 부분은 반으로 갈라 잘게 썰어 준비합니다.\"\n    },\n    {\n      \"stepNumber\": 3,\n      \"description\": \"볼에 진간장, 굴소스, 맛술, 설탕 1큰술, 물엿 2큰술, 매실액, 다진 마늘, 생강가루, 후춧가루, 갈아둔 배와 양파, 대파를 넣고 섞어 양념장을 만듭니다.\"\n    },\n    {\n      \"stepNumber\": 4,\n      \"description\": \"끓는 물 1.5L에 월계수잎과 통후추를 넣고 등갈비와 소주 1잔을 넣어 센 불에서 5분간 삶은 뒤 흐르는 물에 깨끗이 씻어줍니다.\"\n    },\n    {\n      \"stepNumber\": 5,\n      \"description\": \"냄비에 씻은 등갈비, 양념장, 물 500ml를 붓고 센 불에서 10분간 끓입니다.\"\n    },\n    {\n      \"stepNumber\": 6,\n      \"description\": \"약불로 줄인 뒤 뚜껑을 닫고 40분간 더 졸여줍니다.\"\n    },\n    {\n      \"stepNumber\": 7,\n      \"description\": \"양념이 거의 졸아들면 물엿 1큰술을 추가로 넣고 가볍게 섞어 완성합니다.\"\n    }\n  ],\n  \"tags\": [\n    \"한식\",\n    \"찜요리\",\n    \"메인요리\",\n    \"집밥\"\n  ]\n}',
