       (4, 1, 4, 4, 'https://youtube.com/shorts/iMgrGjsL6Ns?si=auFjRjpD5hSt31Vl', 'YOUTUBE',
        '{\n  \"title\": \"오이 비빔국수\",\n  \"description\": \"아삭한 오이와 양파 절임을 곁들여 새콤달콤하게 즐기는 류수영표 비빔국수입니다.\",\n  \"servingSize\": 2,\n  \"cookingTime\": 30,\n  \"cuisineType\": \"KOREAN\",\n  \"mealType\": \"MAIN\",\n  \"difficulty\": \"BEGINNER\",\n  \"ingredients\": [\n    {\n      \"name\": \"오이\",\n      \"amount\": \"1\",\n      \"unit\": \"개\"\n    },\n    {\n      \"name\": \"양파\",\n      \"amount\": \"0.5\",\n      \"unit\": \"개\"\n    },\n    {\n      \"name\": \"설탕\",\n      \"amount\": \"6\",\n      \"unit\": \"큰술\"\n    },\n    {\n      \"name\": \"식초\",\n      \"amount\": \"8\",\n      \"unit\": \"큰술\"\n    },\n    {\n      \"name\": \"맛소금\",\n      \"amount\": \"3\",\n      \"unit\": \"꼬집\"\n    },\n    {\n      \"name\": \"고춧가루\",\n      \"amount\": \"2\",\n      \"unit\": \"큰술\"\n    },\n    {\n      \"name\": \"깨소금\",\n      \"amount\": \"2\",\n      \"unit\": \"큰술\"\n    },\n    {\n      \"name\": \"간장\",\n      \"amount\": \"6\",\n      \"unit\": \"큰술\"\n    },\n    {\n      \"name\": \"다진 마늘\",\n      \"amount\": \"0.5\",\n      \"unit\": \"큰술\"\n    },\n    {\n      \"name\": \"케첩\",\n      \"amount\": \"1\",\n      \"unit\": \"큰술\"\n    },\n    {\n      \"name\": \"고추장\",\n      \"amount\": \"1\",\n      \"unit\": \"큰술\"\n    },\n    {\n      \"name\": \"소면\",\n      \"amount\": \"2\",\n      \"unit\": \"인분\"\n    },\n    {\n      \"name\": \"김\",\n      \"amount\": \"1\",\n      \"unit\": \"장\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": 1,\n      \"description\": \"오이는 최대한 얇게 편 썰고, 양파도 얇게 채 썰어 준비합니다.\"\n    },\n    {\n      \"stepNumber\": 2,\n      \"description\": \"손질한 오이와 양파에 설탕 2, 식초 4, 맛소금 3꼬집을 넣고 버무려 냉장고에서 15분간 절입니다.\"\n    },\n    {\n      \"stepNumber\": 3,\n      \"description\": \"고춧가루 2, 설탕 4, 식초 4, 으깬 깨소금 2, 간장 6, 다진 마늘 0.5, 케첩 1, 고추장 1큰술을 섞어 양념장을 만듭니다.\"\n    },\n    {\n      \"stepNumber\": 4,\n      \"description\": \"양념장에 오이와 양파를 절이며 생긴 채수 4큰술을 넣어 감칠맛을 더합니다.\"\n    },\n    {\n      \"stepNumber\": 5,\n      \"description\": \"소면을 삶아 찬물에 충분히 헹군 뒤 물기를 뺍니다.\"\n    },\n    {\n      \"stepNumber\": 6,\n      \"description\": \"그릇에 면을 담고 잘게 썬 김과 물기를 꽉 짠 오이·양파 절임을 올린 뒤 양념장을 부어 완성합니다.\"\n    }\n  ],\n  \"tags\": [\n    \"한식\",\n    \"면요리\",\n    \"별미\",\n    \"집밥\"\n  ]\n}',
