        '{\n  \"title\": \"크림 치킨 스튜\",\n  \"description\": \"고소한 우유와 생크림 소스에 노릇하게 구운 닭다리살을 넣어 만든 부드러운 스튜입니다.\",\n  \"servingSize\": 2,\n  \"cookingTime\": 30,\n  \"cuisineType\": \"WESTERN\",\n  \"mealType\": \"MAIN\",\n  \"difficulty\": \"BEGINNER\",\n  \"ingredients\": [\n    {\n      \"name\": \"순살 닭다리살\",\n      \"amount\": \"500\",\n      \"unit\": \"g\"\n    },\n    {\n      \"name\": \"양송이버섯\",\n      \"amount\": \"10\",\n      \"unit\": \"개\"\n    },\n    {\n      \"name\": \"다진 마늘\",\n      \"amount\": \"1\",\n      \"unit\": \"티스푼\"\n    },\n    {\n      \"name\": \"우유\",\n      \"amount\": \"200\",\n      \"unit\": \"ml\"\n    },\n    {\n      \"name\": \"생크림\",\n      \"amount\": \"200\",\n      \"unit\": \"ml\"\n    },\n    {\n      \"name\": \"바질\",\n      \"amount\": \"5\",\n      \"unit\": \"장\"\n    },\n    {\n      \"name\": \"올리브유\",\n      \"amount\": \"2\",\n      \"unit\": \"큰술\"\n    },\n    {\n      \"name\": \"소금\",\n      \"amount\": \"0.5\",\n      \"unit\": \"작은술\"\n    },\n    {\n      \"name\": \"후추\",\n      \"amount\": \"0.3\",\n      \"unit\": \"작은술\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": 1,\n      \"description\": \"순살 닭다리살은 키친타월로 수분을 제거한 뒤 소금과 후추로 밑간을 합니다.\"\n    },\n    {\n      \"stepNumber\": 2,\n      \"description\": \"팬에 올리브유를 두르고 닭고기의 껍질 쪽부터 올려 노릇노릇하게 굽습니다.\"\n    },\n    {\n      \"stepNumber\": 3,\n      \"description\": \"양송이버섯을 넣고 소금과 후추로 추가 간을 한 뒤 강불에서 볶습니다.\"\n    },\n    {\n      \"stepNumber\": 4,\n      \"description\": \"다진 마늘 1티스푼을 넣어 재료와 잘 섞이도록 볶아줍니다.\"\n    },\n    {\n      \"stepNumber\": 5,\n      \"description\": \"우유를 먼저 붓고 소스가 어느 정도 졸아들 때까지 끓입니다.\"\n    },\n    {\n      \"stepNumber\": 6,\n      \"description\": \"생크림을 마저 넣고 원하는 농도가 될 때까지 끓여줍니다.\"\n    },\n    {\n      \"stepNumber\": 7,\n      \"description\": \"큼직하게 썬 바질을 넣어 풍미를 더한 뒤 가볍게 섞어 마무리합니다.\"\n    },\n    {\n      \"stepNumber\": 8,\n      \"description\": \"그릇에 담고 남은 바질과 올리브유를 살짝 뿌려 완성합니다.\"\n    }\n  ],\n  \"tags\": [\n    \"양식\",\n    \"스튜\",\n    \"홈파티\",\n    \"브런치\"\n  ]\n}',
