       (6, 1, 6, 6, 'https://youtube.com/shorts/L7_lN6MzWwc?si=fGk0i7HhMIqEWyM2', 'YOUTUBE',
        '{\n    \"title\": \"오무라이스\",\n    \"description\": \"베이컨과 양파를 넣어 고소하게 볶은 밥 위에 부드러운 계란을 얹어 만드는 간단한 한 그릇 요리입니다.\",\n    \"servingSize\": 1,\n    \"cookingTime\": 15,\n    \"cuisineType\": \"FUSION\",\n    \"mealType\": \"MAIN\",\n    \"difficulty\": \"BEGINNER\",\n    \"ingredients\": [\n        {\n            \"name\": \"양파\",\n            \"amount\": \"0.5\",\n            \"unit\": \"개\"\n        },\n        {\n            \"name\": \"베이컨\",\n            \"amount\": \"3\",\n            \"unit\": \"줄\"\n        },\n        {\n            \"name\": \"밥\",\n            \"amount\": \"1\",\n            \"unit\": \"공기\"\n        },\n        {\n            \"name\": \"케첩\",\n            \"amount\": \"4\",\n            \"unit\": \"큰술\"\n        },\n        {\n            \"name\": \"간장\",\n            \"amount\": \"1\",\n            \"unit\": \"큰술\"\n        },\n        {\n            \"name\": \"맛술\",\n            \"amount\": \"1\",\n            \"unit\": \"큰술\"\n        },\n        {\n            \"name\": \"후추\",\n            \"amount\": \"0.1\",\n            \"unit\": \"큰술\"\n        },\n        {\n            \"name\": \"계란\",\n            \"amount\": \"3\",\n            \"unit\": \"개\"\n        },\n        {\n            \"name\": \"소금\",\n            \"amount\": \"2\",\n            \"unit\": \"꼬집\"\n        },\n        {\n            \"name\": \"돈까스 소스\",\n            \"amount\": \"3\",\n            \"unit\": \"큰술\"\n        },\n        {\n            \"name\": \"물\",\n            \"amount\": \"5\",\n            \"unit\": \"큰술\"\n        }\n    ],\n    \"steps\": [\n        {\n            \"stepNumber\": 1,\n            \"description\": \"양파 1/2개와 베이컨 3줄을 적당한 크기로 썰어 준비합니다.\"\n        },\n        {\n            \"stepNumber\": 2,\n            \"description\": \"팬에 기름을 두르고 베이컨과 양파를 볶다가 양파가 투명해지면 밥 1공기와 케첩 2큰술을 넣습니다.\"\n        },\n        {\n            \"stepNumber\": 3,\n            \"description\": \"간장 1큰술, 맛술 1큰술, 후추를 넣고 고르게 볶아준 뒤 접시에 담아 모양을 잡습니다.\"\n        },\n        {\n            \"stepNumber\": 4,\n            \"description\": \"계란 3개에 소금 2꼬집을 섞어 푼 뒤 팬에서 촉촉하게 익혀 밥 위에 덮어줍니다.\"\n        },\n        {\n            \"stepNumber\": 5,\n            \"description\": \"팬에 돈까스 소스 3큰술, 케첩 2큰술, 물 5큰술을 넣고 약불에서 걸쭉하게 끓여 소스를 만듭니다.\"\n        },\n        {\n            \"stepNumber\": 6,\n            \"description\": \"완성된 소스를 계란 위에 골고루 부어 마무리합니다.\"\n        }\n    ],\n    \"tags\": [\n        \"퓨전\",\n        \"한그릇요리\",\n        \"집밥\",\n        \"자취요리\"\n    ]\n}',
