       (7, 1, 7, 7, 'https://youtube.com/shorts/64pZflUA2eA?si=qFcu3LnNpvQjRohB', 'YOUTUBE',
        '{\n    \"title\": \"시장 떡볶이\",\n    \"description\": \"부드러운 밀떡과 어묵이 달콤한 양념에 어우러진 옛날 시장 스타일의 떡볶이입니다.\",\n    \"servingSize\": 2,\n    \"cookingTime\": 30,\n    \"cuisineType\": \"KOREAN\",\n    \"mealType\": \"SNACK\",\n    \"difficulty\": \"BEGINNER\",\n    \"ingredients\": [\n        {\n            \"name\": \"밀떡\",\n            \"amount\": \"300\",\n            \"unit\": \"g\"\n        },\n        {\n            \"name\": \"어묵\",\n            \"amount\": \"3\",\n            \"unit\": \"장\"\n        },\n        {\n            \"name\": \"대파\",\n            \"amount\": \"0.5\",\n            \"unit\": \"대\"\n        },\n        {\n            \"name\": \"고추장\",\n            \"amount\": \"2\",\n            \"unit\": \"큰술\"\n        },\n        {\n            \"name\": \"설탕\",\n            \"amount\": \"3\",\n            \"unit\": \"큰술\"\n        },\n        {\n            \"name\": \"고운 고춧가루\",\n            \"amount\": \"1\",\n            \"unit\": \"큰술\"\n        },\n        {\n            \"name\": \"물엿\",\n            \"amount\": \"3\",\n            \"unit\": \"큰술\"\n        },\n        {\n            \"name\": \"다시다\",\n            \"amount\": \"0.5\",\n            \"unit\": \"큰술\"\n        },\n        {\n            \"name\": \"물\",\n            \"amount\": \"2\",\n            \"unit\": \"컵\"\n        }\n    ],\n    \"steps\": [\n        {\n            \"stepNumber\": 1,\n            \"description\": \"밀떡을 미지근한 물에 1시간 동안 담가 말랑하게 불려줍니다.\"\n        },\n        {\n            \"stepNumber\": 2,\n            \"description\": \"어묵은 떡과 비슷한 크기로 길쭉하게 썰고 대파는 송송 썰어 준비합니다.\"\n        },\n        {\n            \"stepNumber\": 3,\n            \"description\": \"팬에 물, 고추장, 설탕, 고운 고춧가루, 물엿, 다시다를 넣고 잘 풀어줍니다.\"\n        },\n        {\n            \"stepNumber\": 4,\n            \"description\": \"불린 떡과 어묵을 넣고 양념이 반 정도 줄어들 때까지 은근하게 끓여줍니다.\"\n        },\n        {\n            \"stepNumber\": 5,\n            \"description\": \"국물이 걸쭉해지면 썰어둔 대파를 넣고 가볍게 버무려 완성합니다.\"\n        }\n    ],\n    \"tags\": [\n        \"분식\",\n        \"간식\",\n        \"추억의맛\",\n        \"길거리음식\"\n    ]\n}',
