        '{\n    \"title\": \"계란국\",\n    \"description\": \"코인 육수를 활용하여 누구나 쉽고 빠르게 끓일 수 있는 담백하고 고소한 계란국입니다.\",\n    \"servingSize\": 2,\n    \"cookingTime\": 10,\n    \"cuisineType\": \"KOREAN\",\n    \"mealType\": \"SIDE_DISH\",\n    \"difficulty\": \"BEGINNER\",\n    \"ingredients\": [\n        {\"name\": \"물\", \"amount\": \"600\", \"unit\": \"ml\"},\n        {\"name\": \"코인 육수\", \"amount\": \"1\", \"unit\": \"개\"},\n        {\"name\": \"간장\", \"amount\": \"0.5\", \"unit\": \"큰술\"},\n        {\"name\": \"소금\", \"amount\": \"1\", \"unit\": \"꼬집\"},\n        {\"name\": \"계란\", \"amount\": \"2\", \"unit\": \"개\"},\n        {\"name\": \"대파\", \"amount\": \"10\", \"unit\": \"g\"},\n        {\"name\": \"참기름\", \"amount\": \"0.5\", \"unit\": \"큰술\"},\n        {\"name\": \"후추\", \"amount\": \"0.1\", \"unit\": \"g\"}\n    ],\n    \"steps\": [\n        {\"stepNumber\": 1, \"description\": \"냄비에 물 600ml, 코인 육수 1개, 간장 0.5큰술, 소금 한 꼬집을 넣고 끓입니다.\"},\n        {\"stepNumber\": 2, \"description\": \"육수가 끓어오르면 미리 풀어둔 계란 2개를 휘휘 둘러서 넣어줍니다.\"},\n        {\"stepNumber\": 3, \"description\": \"계란이 몽글몽글하게 익도록 약 15초 정도 기다린 후에 저어줍니다.\"},\n        {\"stepNumber\": 4, \"description\": \"송송 썬 대파, 참기름 0.5큰술, 후추를 약간 넣어 마무리합니다.\"}\n    ],\n    \"tags\": [\"한식\", \"국\", \"자취요리\", \"간편요리\"]\n}',
