       (9, 1, 9, 9, 'https://youtube.com/shorts/AWrdLt0kYbA?si=_gBhCb_yjFk1HDuh', 'YOUTUBE',
        '{\n    \"title\": \"새우 채소 구이\",\n    \"description\": \"배우 이시영의 다이어트 식단으로 유명하며, 새우와 구운 채소에 특제 소스를 곁들여 포만감이 높은 건강식입니다.\",\n    \"servingSize\": 1,\n    \"cookingTime\": 15,\n    \"cuisineType\": \"KOREAN\",\n    \"mealType\": \"MAIN\",\n    \"difficulty\": \"BEGINNER\",\n    \"ingredients\": [\n        {\"name\": \"당근\", \"amount\": \"0.5\", \"unit\": \"개\"},\n        {\"name\": \"애호박\", \"amount\": \"0.5\", \"unit\": \"개\"},\n        {\"name\": \"표고버섯\", \"amount\": \"2\", \"unit\": \"개\"},\n        {\"name\": \"새우\", \"amount\": \"6\", \"unit\": \"마리\"},\n        {\"name\": \"올리브유\", \"amount\": \"1\", \"unit\": \"큰술\"},\n        {\"name\": \"소금\", \"amount\": \"0.1\", \"unit\": \"작은술\"},\n        {\"name\": \"후추\", \"amount\": \"0.1\", \"unit\": \"작은술\"},\n        {\"name\": \"간장\", \"amount\": \"1\", \"unit\": \"큰술\"},\n        {\"name\": \"식초\", \"amount\": \"1\", \"unit\": \"큰술\"},\n        {\"name\": \"다진 마늘\", \"amount\": \"0.5\", \"unit\": \"큰술\"},\n        {\"name\": \"참기름\", \"amount\": \"1\", \"unit\": \"큰술\"},\n        {\"name\": \"통깨\", \"amount\": \"0.5\", \"unit\": \"큰술\"}\n    ],\n    \"steps\": [\n        {\"stepNumber\": 1, \"description\": \"당근, 애호박, 표고버섯을 먹기 좋은 크기로 썰어 준비합니다.\"},\n        {\"stepNumber\": 2, \"description\": \"분량의 간장, 식초, 다진 마늘, 참기름, 통깨를 섞어 드레싱 소스를 만듭니다.\"},\n        {\"stepNumber\": 3, \"description\": \"팬에 올리브유를 두르고 준비한 채소와 새우를 올립니다.\"},\n        {\"stepNumber\": 4, \"description\": \"소금과 후추를 골고루 뿌려 앞뒤로 노릇하게 구워줍니다.\"},\n        {\"stepNumber\": 5, \"description\": \"잘 구워진 재료를 그릇에 담고 소스를 뿌려 마무리합니다.\"}\n    ],\n    \"tags\": [\"다이어트\", \"건강식\", \"저칼로리\", \"원팬요리\"]\n}',
