       (10, 1, 10, 10, 'https://youtube.com/shorts/WRvyyScVKdw?si=hfU_QksIG-IcYYKs', 'YOUTUBE',
        '{\n    \"title\": \"버터치킨카레\",\n    \"description\": \"버터와 생크림의 부드러운 고소함이 일품인 인도식 카레 요리입니다.\",\n    \"servingSize\": 2,\n    \"cookingTime\": 40,\n    \"cuisineType\": \"ASIAN\",\n    \"mealType\": \"MAIN\",\n    \"difficulty\": \"BEGINNER\",\n    \"ingredients\": [\n        {\"name\": \"닭다리살\", \"amount\": \"300\", \"unit\": \"g\"},\n        {\"name\": \"우유\", \"amount\": \"200\", \"unit\": \"ml\"},\n        {\"name\": \"양파\", \"amount\": \"1\", \"unit\": \"개\"},\n        {\"name\": \"감자\", \"amount\": \"1\", \"unit\": \"개\"},\n        {\"name\": \"당근\", \"amount\": \"0.5\", \"unit\": \"개\"},\n        {\"name\": \"버터\", \"amount\": \"20\", \"unit\": \"g\"},\n        {\"name\": \"물\", \"amount\": \"450\", \"unit\": \"ml\"},\n        {\"name\": \"소금\", \"amount\": \"0.1\", \"unit\": \"큰술\"},\n        {\"name\": \"후추\", \"amount\": \"0.1\", \"unit\": \"큰술\"},\n        {\"name\": \"다진마늘\", \"amount\": \"1\", \"unit\": \"큰술\"},\n        {\"name\": \"치킨스톡\", \"amount\": \"0.5\", \"unit\": \"개\"},\n        {\"name\": \"고체카레\", \"amount\": \"3\", \"unit\": \"조각\"},\n        {\"name\": \"생크림\", \"amount\": \"75\", \"unit\": \"ml\"},\n        {\"name\": \"파슬리가루\", \"amount\": \"0.1\", \"unit\": \"큰술\"}\n    ],\n    \"steps\": [\n        {\"stepNumber\": 1, \"description\": \"닭살을 우유에 10분간 담가 잡내를 제거합니다.\"},\n        {\"stepNumber\": 2, \"description\": \"양파는 채 썰고 감자와 당근은 한입 크기로 썰어 준비합니다.\"},\n        {\"stepNumber\": 3, \"description\": \"팬에 버터를 녹인 뒤 양파가 갈색으로 변할 때까지 충분히 볶습니다.\"},\n        {\"stepNumber\": 4, \"description\": \"볶은 양파에 감자와 당근을 넣고 살짝 볶은 후 물 450ml를 넣고 뚜껑을 덮어 익힙니다.\"},\n        {\"stepNumber\": 5, \"description\": \"우유에 재워둔 닭살의 물기를 제거하고 소금, 후추, 다진마늘로 밑간을 합니다.\"},\n        {\"stepNumber\": 6, \"description\": \"팬에 밑간한 닭살을 앞뒤로 노릇하게 구워줍니다.\"},\n        {\"stepNumber\": 7, \"description\": \"채소가 다 익으면 치킨스톡과 고체카레를 넣어 뭉치지 않게 잘 풀어주며 끓입니다.\"},\n        {\"stepNumber\": 8, \"description\": \"생크림을 넣고 잘 섞어준 뒤 파슬리 가루를 뿌립니다.\"},\n        {\"stepNumber\": 9, \"description\": \"마지막으로 구워둔 닭살을 카레 위에 올려 완성합니다.\"}\n    ],\n    \"tags\": [\"카레\", \"일품요리\", \"홈쿡\", \"인도식\"]\n}',
