       (11, 1, 11, 11, 'https://youtube.com/shorts/rX7tvm_viIA?si=LaDsl_PHp6o2pjLV', 'YOUTUBE',
        '{\n    \"title\": \"우삼겹 덮밥\",\n    \"description\": \"달콤 짭조름한 소스에 볶아낸 우삼겹과 부드러운 수란을 곁들인 든든한 한 그릇 요리입니다.\",\n    \"servingSize\": 1,\n    \"cookingTime\": 15,\n    \"cuisineType\": \"KOREAN\",\n    \"mealType\": \"MAIN\",\n    \"difficulty\": \"BEGINNER\",\n    \"ingredients\": [\n        {\"name\": \"우삼겹\", \"amount\": \"120\", \"unit\": \"g\"},\n        {\"name\": \"양파\", \"amount\": \"0.25\", \"unit\": \"개\"},\n        {\"name\": \"진간장\", \"amount\": \"1.5\", \"unit\": \"큰술\"},\n        {\"name\": \"알룰로스\", \"amount\": \"0.8\", \"unit\": \"큰술\"},\n        {\"name\": \"맛술\", \"amount\": \"1\", \"unit\": \"큰술\"},\n        {\"name\": \"다진마늘\", \"amount\": \"1\", \"unit\": \"큰술\"},\n        {\"name\": \"후추\", \"amount\": \"1\", \"unit\": \"꼬집\"},\n        {\"name\": \"레드페퍼\", \"amount\": \"1\", \"unit\": \"꼬집\"},\n        {\"name\": \"계란\", \"amount\": \"1\", \"unit\": \"개\"},\n        {\"name\": \"식초\", \"amount\": \"1\", \"unit\": \"큰술\"},\n        {\"name\": \"대파\", \"amount\": \"10\", \"unit\": \"g\"},\n        {\"name\": \"와사비\", \"amount\": \"5\", \"unit\": \"g\"},\n        {\"name\": \"밥\", \"amount\": \"1\", \"unit\": \"공기\"}\n    ],\n    \"steps\": [\n        {\"stepNumber\": 1, \"description\": \"양파 1/4개를 얇게 채 썰어 준비합니다.\"},\n        {\"stepNumber\": 2, \"description\": \"진간장, 알룰로스, 맛술, 다진마늘을 섞어 양념장을 만듭니다.\"},\n        {\"stepNumber\": 3, \"description\": \"팬에 우삼겹을 넣고 약불에서 핏기가 사라질 때까지 천천히 볶습니다.\"},\n        {\"stepNumber\": 4, \"description\": \"핏기가 사라지면 채 썬 양파와 후추를 넣고 약불에서 1분간 더 볶습니다.\"},\n        {\"stepNumber\": 5, \"description\": \"준비한 소스와 레드페퍼를 넣고 중불에서 물기가 살짝 남을 때까지 빠르게 졸입니다.\"},\n        {\"stepNumber\": 6, \"description\": \"그릇에 물 2/3컵, 식초 1큰술, 계란 1개를 넣고 노른자를 살짝 찌른 후 전자레인지에서 1분 30초간 돌려 수란을 만듭니다.\"},\n        {\"stepNumber\": 7, \"description\": \"밥 위에 볶은 우삼겹, 수란, 대파, 와사비를 취향껏 올려 마무리합니다.\"}\n    ],\n    \"tags\": [\"덮밥\", \"혼밥\", \"고기요리\", \"한그릇요리\"]\n}',
        NULL, NULL, 'COMPLETED', '2026-02-16 03:36:36.323896', '2026-02-16 03:37:03.459442'),
       (12, 1, 12, 12, 'https://youtube.com/shorts/me0jvPhYq8s?si=i2cDTumI2bp9klW8', 'YOUTUBE',
        '{\n    \"title\": \"참치 삼각김밥\",\n    \"description\": \"전용 틀 없이도 집에서 간편하게 여러 개의 삼각김밥을 한 번에 만드는 방법입니다.\",\n    \"servingSize\": 2,\n    \"cookingTime\": 15,\n    \"cuisineType\": \"KOREAN\",\n    \"mealType\": \"SNACK\",\n    \"difficulty\": \"BEGINNER\",\n    \"ingredients\": [\n        {\"name\": \"밥\", \"amount\": \"2\", \"unit\": \"공기\"},\n        {\"name\": \"소금\", \"amount\": \"0.3\", \"unit\": \"큰술\"},\n        {\"name\": \"참기름\", \"amount\": \"1\", \"unit\": \"큰술\"},\n        {\"name\": \"깨\", \"amount\": \"1\", \"unit\": \"작은술\"},\n        {\"name\": \"씻은 김치\", \"amount\": \"50\", \"unit\": \"g\"},\n        {\"name\": \"참치 통조림\", \"amount\": \"1\", \"unit\": \"캔\"},\n        {\"name\": \"마요네즈\", \"amount\": \"2\", \"unit\": \"큰술\"},\n        {\"name\": \"깻잎\", \"amount\": \"4\", \"unit\": \"장\"},\n        {\"name\": \"김밥용 김\", \"amount\": \"1\", \"unit\": \"장\"}\n    ],\n    \"steps\": [\n        {\"stepNumber\": 1, \"description\": \"밥에 소금, 참기름, 깨를 뿌려 골고루 섞어 밑간을 합니다.\"},\n        {\"stepNumber\": 2, \"description\": \"씻은 김치를 잘게 자른 뒤, 기름을 뺀 참치와 마요네즈 2큰술을 넣고 버무립니다.\"},\n        {\"stepNumber\": 3, \"description\": \"네모난 그릇에 랩을 깔고 밥, 깻잎, 참치마요 속재료를 순서대로 올린 뒤 다시 밥으로 덮어줍니다.\"},\n        {\"stepNumber\": 4, \"description\": \"그릇에서 내용물을 꺼내 도마 위에 뒤집어 놓고 랩을 벗겨냅니다.\"},\n        {\"stepNumber\": 5, \"description\": \"칼을 이용해 X자로 잘라 4개의 삼각형 모양으로 만듭니다.\"},\n        {\"stepNumber\": 6, \"description\": \"김밥용 김을 4등분하여 각 삼각형의 밑부분에 붙여 완성합니다.\"}\n    ],\n    \"tags\": [\"한식\", \"도시락\", \"간편식\", \"자취요리\"]\n}',
        NULL, NULL, 'COMPLETED', '2026-02-16 03:36:50.075690', '2026-02-16 03:37:13.931707'),
       (13, 1, 13, 13, 'https://youtube.com/shorts/cGp47dRy3n0?si=12XjohRROSRmq5o5', 'YOUTUBE',
        '{\n  \"title\": \"소갈비찜\",\n  \"description\": \"일반 냄비로도 고기가 부드럽게 쏙 빠지는 달콤 짭짤한 소갈비찜 레시피입니다.\",\n  \"servingSize\": 4,\n  \"cookingTime\": 160,\n  \"cuisineType\": \"KOREAN\",\n  \"mealType\": \"MAIN\",\n  \"difficulty\": \"INTERMEDIATE\",\n  \"ingredients\": [\n    {\"name\": \"소갈비\", \"amount\": \"2\", \"unit\": \"kg\"},\n    {\"name\": \"설탕\", \"amount\": \"4\", \"unit\": \"큰술\"},\n    {\"name\": \"소주\", \"amount\": \"50\", \"unit\": \"ml\"},\n    {\"name\": \"대파\", \"amount\": \"2\", \"unit\": \"개\"},\n    {\"name\": \"양파\", \"amount\": \"1\", \"unit\": \"개\"},\n    {\"name\": \"무\", \"amount\": \"350\", \"unit\": \"g\"},\n    {\"name\": \"통후추\", \"amount\": \"1\", \"unit\": \"큰술\"},\n    {\"name\": \"물\", \"amount\": \"3\", \"unit\": \"L\"},\n    {\"name\": \"배즙\", \"amount\": \"200\", \"unit\": \"ml\"},\n    {\"name\": \"진간장\", \"amount\": \"150\", \"unit\": \"ml\"},\n    {\"name\": \"다진 마늘\", \"amount\": \"4\", \"unit\": \"큰술\"},\n    {\"name\": \"다진 생강\", \"amount\": \"0.33\", \"unit\": \"큰술\"},\n    {\"name\": \"맛술\", \"amount\": \"5\", \"unit\": \"큰술\"},\n    {\"name\": \"참기름\", \"amount\": \"2\", \"unit\": \"큰술\"},\n    {\"name\": \"올리고당\", \"amount\": \"7\", \"unit\": \"큰술\"},\n    {\"name\": \"후추\", \"amount\": \"0.1\", \"unit\": \"큰술\"},\n    {\"name\": \"대추\", \"amount\": \"10\", \"unit\": \"개\"},\n    {\"name\": \"밤\", \"amount\": \"6\", \"unit\": \"개\"},\n    {\"name\": \"당근\", \"amount\": \"0.5\", \"unit\": \"개\"},\n    {\"name\": \"청양고추\", \"amount\": \"5\", \"unit\": \"개\"}\n  ],\n  \"steps\": [\n    {\"stepNumber\": 1, \"description\": \"소갈비는 설탕 4큰술을 넣은 찬물에 1시간 동안 담가 핏물을 제거합니다.\"},\n    {\"stepNumber\": 2, \"description\": \"끓는 물에 소주를 약간 넣고 갈비를 3분간 데친 후 찬물에 헹궈냅니다.\"},\n    {\"stepNumber\": 3, \"description\": \"냄비에 갈비, 대파 1대, 양파 반 개, 무 1토막, 통후추 1큰술, 소주 50ml, 물 3L를 넣고 1시간 동안 푹 끓입니다.\"},\n    {\"stepNumber\": 4, \"description\": \"양파 반 개와 대파 흰 부분을 배즙과 함께 믹서기에 갈아줍니다.\"},\n    {\"stepNumber\": 5, \"description\": \"갈아둔 베이스에 간장, 다진 마늘, 생강, 맛술, 참기름, 올리고당, 설탕, 후추를 섞어 양념장을 만듭니다.\"},\n    {\"stepNumber\": 6, \"description\": \"삶아진 고기와 육수를 분리하고 육수는 기름을 제거하여 1L를 준비합니다.\"},\n    {\"stepNumber\": 7, \"description\": \"냄비에 고기, 육수 1L, 양념장을 넣고 뚜껑을 덮어 20분간 조립니다.\"},\n    {\"stepNumber\": 8, \"description\": \"손질한 무를 넣고 10~12분 더 조린 후, 당근과 밤을 넣어 5분간 더 끓입니다.\"},\n    {\"stepNumber\": 9, \"description\": \"마지막으로 대추와 청양고추를 넣고 한소끔 더 끓여 완성합니다.\"}\n  ],\n  \"tags\": [\"한식\", \"찜\", \"집밥\", \"명절요리\", \"전통음식\"]\n}',
        NULL, NULL, 'COMPLETED', '2026-02-16 03:37:01.968886', '2026-02-16 03:37:32.315190'),
       (14, 1, 14, 14, 'https://youtube.com/shorts/D2Ez923DEtE?si=h50xN07fmmVsbI5p', 'YOUTUBE',
        '{\n    \"title\": \"새우 원팬 파스타\",\n    \"description\": \"설거지 걱정 없이 팬 하나로 간편하게 완성하는 감칠맛 가득한 새우 파스타입니다.\",\n    \"servingSize\": 1,\n    \"cookingTime\": 15,\n    \"cuisineType\": \"WESTERN\",\n    \"mealType\": \"MAIN\",\n    \"difficulty\": \"BEGINNER\",\n    \"ingredients\": [\n        {\"name\": \"올리브 오일\", \"amount\": \"4\", \"unit\": \"큰술\"},\n        {\"name\": \"다진 마늘\", \"amount\": \"1\", \"unit\": \"큰술\"},\n        {\"name\": \"파스타면\", \"amount\": \"100\", \"unit\": \"g\"},\n        {\"name\": \"물\", \"amount\": \"500\", \"unit\": \"ml\"},\n        {\"name\": \"참치액\", \"amount\": \"1\", \"unit\": \"큰술\"},\n        {\"name\": \"굴소스\", \"amount\": \"1\", \"unit\": \"큰술\"},\n        {\"name\": \"새우\", \"amount\": \"6\", \"unit\": \"개\"},\n        {\"name\": \"편마늘\", \"amount\": \"5\", \"unit\": \"알\"}\n    ],\n    \"steps\": [\n        {\"stepNumber\": 1, \"description\": \"팬에 올리브 오일 3바퀴를 두르고 다진 마늘을 넣어 약불에서 볶습니다.\"},\n        {\"stepNumber\": 2, \"description\": \"마늘 향이 올라오면 파스타면을 넣고 물 500ml를 붓습니다.\"},\n        {\"stepNumber\": 3, \"description\": \"참치액 1큰술과 굴소스 1큰술을 넣어 감칠맛을 더합니다.\"},\n        {\"stepNumber\": 4, \"description\": \"준비한 새우와 편마늘을 팬에 함께 넣습니다.\"},\n        {\"stepNumber\": 5, \"description\": \"물이 졸아들고 면이 익을 때까지 약 10분 정도 끓입니다.\"},\n        {\"stepNumber\": 6, \"description\": \"마지막으로 올리브 오일을 한 바퀴 더 둘러 풍미를 살려 완성합니다.\"}\n    ],\n    \"tags\": [\"원팬요리\", \"파스타\", \"양식\", \"자취요리\"]\n}',
