       (15, 1, 15, 15, 'https://youtube.com/shorts/N6g-mZXEr60?si=z9cJbwnkgtdqwrom', 'YOUTUBE',
        '{\n    \"title\": \"떡갈비\",\n    \"description\": \"소고기와 돼지고기를 섞어 풍부한 육즙과 쫀득한 식감을 살린 정통 떡갈비 레시피입니다.\",\n    \"servingSize\": 4,\n    \"cookingTime\": 150,\n    \"cuisineType\": \"KOREAN\",\n    \"mealType\": \"MAIN\",\n    \"difficulty\": \"BEGINNER\",\n    \"ingredients\": [\n        {\"name\": \"다짐육 소고기\", \"amount\": \"300\", \"unit\": \"g\"},\n        {\"name\": \"다짐육 돼지고기\", \"amount\": \"300\", \"unit\": \"g\"},\n        {\"name\": \"양파\", \"amount\": \"1\", \"unit\": \"개\"},\n        {\"name\": \"대파\", \"amount\": \"1\", \"unit\": \"뿌리\"},\n        {\"name\": \"다진 마늘\", \"amount\": \"1\", \"unit\": \"큰술\"},\n        {\"name\": \"생강\", \"amount\": \"0.5\", \"unit\": \"큰술\"},\n        {\"name\": \"간장\", \"amount\": \"4\", \"unit\": \"큰술\"},\n        {\"name\": \"참기름\", \"amount\": \"2\", \"unit\": \"큰술\"},\n        {\"name\": \"물엿\", \"amount\": \"2\", \"unit\": \"큰술\"},\n        {\"name\": \"맛술\", \"amount\": \"3\", \"unit\": \"큰술\"},\n        {\"name\": \"후추\", \"amount\": \"0.5\", \"unit\": \"작은술\"},\n        {\"name\": \"찹쌀가루\", \"amount\": \"4\", \"unit\": \"큰술\"}\n    ],\n    \"steps\": [\n        {\"stepNumber\": 1, \"description\": \"잘게 자른 양파, 대파와 함께 모든 양념 재료를 볼에 담습니다.\"},\n        {\"stepNumber\": 2, \"description\": \"모든 재료가 잘 섞이도록 충분히 치대어 반죽합니다.\"},\n        {\"stepNumber\": 3, \"description\": \"반죽을 냉장고에 넣고 2시간 이상 숙성시켜 풍미를 더합니다.\"},\n        {\"stepNumber\": 4, \"description\": \"숙성된 반죽을 둥글납작한 모양으로 빚어줍니다.\"},\n        {\"stepNumber\": 5, \"description\": \"팬에 기름을 두르고 뚜껑을 덮어 앞뒤로 노릇하게 굽습니다.\"},\n        {\"stepNumber\": 6, \"description\": \"마지막에 뚜껑을 열고 뒤집어가며 양념이 잘 배어들도록 바짝 조려 완성합니다.\"}\n    ],\n    \"tags\": [\"한식\", \"고기요리\", \"명절음식\", \"집밥\"]\n}',
