       (16, 1, 16, 16, 'https://youtube.com/shorts/LiiXKJ_Juvs?si=Wy5482IItO_szMH8', 'YOUTUBE',
        '{\n    \"title\": \"안성재 계란김밥\",\n    \"description\": \"버터와 카레가루를 더해 풍미를 살린 안성재 셰프 스타일의 고소하고 담백한 계란김밥입니다.\",\n    \"servingSize\": 2,\n    \"cookingTime\": 20,\n    \"cuisineType\": \"KOREAN\",\n    \"mealType\": \"MAIN\",\n    \"difficulty\": \"BEGINNER\",\n    \"ingredients\": [\n        {\"name\": \"계란\", \"amount\": \"4\", \"unit\": \"개\"},\n        {\"name\": \"맛술\", \"amount\": \"1\", \"unit\": \"큰술\"},\n        {\"name\": \"카레가루\", \"amount\": \"0.25\", \"unit\": \"큰술\"},\n        {\"name\": \"식용유\", \"amount\": \"1\", \"unit\": \"큰술\"},\n        {\"name\": \"버터\", \"amount\": \"1.5\", \"unit\": \"큰술\"},\n        {\"name\": \"밥\", \"amount\": \"1.5\", \"unit\": \"공기\"},\n        {\"name\": \"진간장\", \"amount\": \"1\", \"unit\": \"큰술\"},\n        {\"name\": \"참기름\", \"amount\": \"1\", \"unit\": \"큰술\"},\n        {\"name\": \"김밥용 김\", \"amount\": \"2\", \"unit\": \"장\"}\n    ],\n    \"steps\": [\n        {\"stepNumber\": 1, \"description\": \"계란 4개에 맛술 1큰술, 카레가루 1/4큰술을 넣고 잘 섞은 뒤 체에 한 번 걸러줍니다.\"},\n        {\"stepNumber\": 2, \"description\": \"팬에 식용유를 두르고 계란물을 부어 스크램블을 만들다가 버터 0.5큰술을 넣어 버터 향을 입힙니다.\"},\n        {\"stepNumber\": 3, \"description\": \"밥 1.5공기에 버터 1큰술, 간장 1큰술, 참기름 약간을 넣어 밑간을 합니다.\"},\n        {\"stepNumber\": 4, \"description\": \"김 위에 밑간한 밥을 얇게 펴고 그 위에 스크램블 에그를 듬뿍 올려 돌돌 말아줍니다.\"},\n        {\"stepNumber\": 5, \"description\": \"완성된 김밥 표면에 참기름을 살짝 발라 마무리합니다.\"}\n    ],\n    \"tags\": [\"김밥\", \"한식\", \"분식\", \"간단요리\", \"집밥\"]\n}',
        NULL, NULL, 'COMPLETED', '2026-02-16 03:37:56.117102', '2026-02-16 03:38:22.078471'),
       (17, 1, 17, 17, 'https://youtube.com/shorts/oUxlTCGqOUg?si=ziYmGfL5CDDKWIPI', 'YOUTUBE',
        '{\n    \"title\": \"브로콜리 참깨 무침\",\n    \"description\": \"고소한 참깨 드레싱과 아삭한 브로콜리가 어우러진 영양 가득한 건강 반찬입니다.\",\n    \"servingSize\": 2,\n    \"cookingTime\": 15,\n    \"cuisineType\": \"KOREAN\",\n    \"mealType\": \"SIDE_DISH\",\n    \"difficulty\": \"BEGINNER\",\n    \"ingredients\": [\n        {\"name\": \"브로콜리\", \"amount\": \"150\", \"unit\": \"g\"},\n        {\"name\": \"삶은 달걀\", \"amount\": \"2\", \"unit\": \"개\"},\n        {\"name\": \"베이컨\", \"amount\": \"3\", \"unit\": \"줄\"},\n        {\"name\": \"식초\", \"amount\": \"2\", \"unit\": \"큰술\"},\n        {\"name\": \"볶은 참깨\", \"amount\": \"3\", \"unit\": \"큰술\"},\n        {\"name\": \"간장\", \"amount\": \"0.5\", \"unit\": \"큰술\"},\n        {\"name\": \"알룰로스\", \"amount\": \"1\", \"unit\": \"큰술\"},\n        {\"name\": \"마요네즈\", \"amount\": \"3\", \"unit\": \"큰술\"},\n        {\"name\": \"소금\", \"amount\": \"1\", \"unit\": \"꼬집\"},\n        {\"name\": \"후추\", \"amount\": \"1\", \"unit\": \"꼬집\"}\n    ],\n    \"steps\": [\n        {\"stepNumber\": 1, \"description\": \"물에 식초 2스푼을 풀어 브로콜리를 깨끗하게 씻어줍니다.\"},\n        {\"stepNumber\": 2, \"description\": \"브로콜리를 먹기 좋은 크기로 자르고, 줄기 부분은 껍질을 벗겨낸 뒤 잘라줍니다.\"},\n        {\"stepNumber\": 3, \"description\": \"끓는 물에 손질한 브로콜리를 넣고 1분간 데친 후 찬물에 헹궈 물기를 제거합니다.\"},\n        {\"stepNumber\": 4, \"description\": \"갈아놓은 참깨 3, 간장 0.5, 알룰로스 1, 마요네즈 3, 소금 1꼬집을 섞어 소스를 만듭니다.\"},\n        {\"stepNumber\": 5, \"description\": \"볼에 데친 브로콜리, 자른 삶은 달걀, 구운 베이컨을 한데 담습니다.\"},\n        {\"stepNumber\": 6, \"description\": \"준비한 참깨 소스와 후추를 넣고 재료가 으깨지지 않도록 살살 버무려 완성합니다.\"}\n    ],\n    \"tags\": [\"건강식\", \"밑반찬\", \"샐러드\", \"다이어트\"]\n}',
        NULL, NULL, 'COMPLETED', '2026-02-16 03:38:20.950590', '2026-02-16 03:38:48.159058'),
       (18, 1, 18, 18, 'https://youtube.com/shorts/Nn4kK5gmKXE?si=L8yJ2r8NhoUgY7Wd', 'YOUTUBE',
        '{\n    \"title\": \"햄치즈 토스트\",\n    \"description\": \"달콤한 키위 소스가 매력적인 이삭토스트 스타일의 햄치즈 토스트입니다.\",\n    \"servingSize\": 1,\n    \"cookingTime\": 10,\n    \"cuisineType\": \"KOREAN\",\n    \"mealType\": \"SNACK\",\n    \"difficulty\": \"BEGINNER\",\n    \"ingredients\": [\n        {\"name\": \"양배추\", \"amount\": \"50\", \"unit\": \"g\"},\n        {\"name\": \"계란\", \"amount\": \"1\", \"unit\": \"개\"},\n        {\"name\": \"소금\", \"amount\": \"1\", \"unit\": \"꼬집\"},\n        {\"name\": \"옥수수콘\", \"amount\": \"1\", \"unit\": \"큰술\"},\n        {\"name\": \"마요네즈\", \"amount\": \"2\", \"unit\": \"큰술\"},\n        {\"name\": \"설탕\", \"amount\": \"1\", \"unit\": \"큰술\"},\n        {\"name\": \"키위드레싱\", \"amount\": \"2\", \"unit\": \"큰술\"},\n        {\"name\": \"버터\", \"amount\": \"20\", \"unit\": \"g\"},\n        {\"name\": \"슬라이스 햄\", \"amount\": \"1\", \"unit\": \"장\"},\n        {\"name\": \"식빵\", \"amount\": \"2\", \"unit\": \"장\"},\n        {\"name\": \"체다치즈\", \"amount\": \"1\", \"unit\": \"장\"}\n    ],\n    \"steps\": [\n        {\"stepNumber\": 1, \"description\": \"양배추를 얇게 채 썹니다.\"},\n        {\"stepNumber\": 2, \"description\": \"그릇에 계란 1개, 소금 한 꼬집, 옥수수콘 1큰술을 넣고 골고루 섞어줍니다.\"},\n        {\"stepNumber\": 3, \"description\": \"마요네즈 2큰술, 설탕 1큰술, 키위드레싱 2큰술을 섞어 소스를 만듭니다.\"},\n        {\"stepNumber\": 4, \"description\": \"팬에 버터를 녹여 슬라이스 햄을 굽고, 옆에 계란물을 부어 식빵 크기로 모양을 잡아 굽습니다.\"},\n        {\"stepNumber\": 5, \"description\": \"팬에 다시 버터를 두르고 식빵 2장을 앞뒤로 노릇하게 구워줍니다.\"},\n        {\"stepNumber\": 6, \"description\": \"구워진 식빵의 한쪽 면에 미리 만들어둔 소스를 펴 바릅니다.\"},\n        {\"stepNumber\": 7, \"description\": \"소스 바른 식빵 위에 계란, 햄, 채 썬 양배추, 체다치즈를 올리고 남은 식빵으로 덮어 완성합니다.\"}\n    ],\n    \"tags\": [\"토스트\", \"샌드위치\", \"간식\", \"길거리음식\"]\n}',
        NULL, NULL, 'COMPLETED', '2026-02-16 03:38:48.378237', '2026-02-16 03:39:16.832585'),
