        '{\n    \"title\": \"원팬 크림 파스타\",\n    \"description\": \"팬 하나로 설거지 걱정 없이 간편하게 완성하는 고소하고 꾸덕한 크림 파스타입니다.\",\n    \"servingSize\": 1,\n    \"cookingTime\": 15,\n    \"cuisineType\": \"WESTERN\",\n    \"mealType\": \"MAIN\",\n    \"difficulty\": \"BEGINNER\",\n    \"ingredients\": [\n        {\n            \"name\": \"식용유\",\n            \"amount\": \"2\",\n            \"unit\": \"큰술\"\n        },\n        {\n            \"name\": \"양파\",\n            \"amount\": \"0.5\",\n            \"unit\": \"개\"\n        },\n        {\n            \"name\": \"다진 마늘\",\n            \"amount\": \"1\",\n            \"unit\": \"큰술\"\n        },\n        {\n            \"name\": \"베이컨\",\n            \"amount\": \"4\",\n            \"unit\": \"줄\"\n        },\n        {\n            \"name\": \"물\",\n            \"amount\": \"500\",\n            \"unit\": \"ml\"\n        },\n        {\n            \"name\": \"우유\",\n            \"amount\": \"200\",\n            \"unit\": \"ml\"\n        },\n        {\n            \"name\": \"소금\",\n            \"amount\": \"0.5\",\n            \"unit\": \"큰술\"\n        },\n        {\n            \"name\": \"체다치즈\",\n            \"amount\": \"2\",\n            \"unit\": \"장\"\n        },\n        {\n            \"name\": \"양송이버섯\",\n            \"amount\": \"4\",\n            \"unit\": \"개\"\n        },\n        {\n            \"name\": \"파스타면\",\n            \"amount\": \"100\",\n            \"unit\": \"g\"\n        }\n    ],\n    \"steps\": [\n        {\n            \"stepNumber\": 1,\n            \"description\": \"팬에 식용유를 두르고 다진 양파와 다진 마늘을 넣고 볶습니다.\"\n        },\n        {\n            \"stepNumber\": 2,\n            \"description\": \"베이컨을 넣고 노릇하게 볶아줍니다.\"\n        },\n        {\n            \"stepNumber\": 3,\n            \"description\": \"물, 우유, 소금, 치즈, 양송이버섯을 모두 넣습니다.\"\n        },\n        {\n            \"stepNumber\": 4,\n            \"description\": \"파스타면을 넣고 소스가 꾸덕해질 때까지 졸여서 완성합니다.\"\n        }\n    ],\n    \"tags\": [\n        \"양식\",\n        \"원팬요리\",\n        \"파스타\",\n        \"자취요리\"\n    ]\n}',
