       (20, 1, 20, 20, 'https://youtube.com/shorts/wepwfXk1mok?si=ne36RHoRKXUALL8-', 'YOUTUBE',
        '{\n    \"title\": \"가지 포두부 라자냐\",\n    \"description\": \"밀가루 대신 포두부와 가지를 활용해 탄수화물을 줄이고 건강을 챙긴 라자냐 레시피입니다.\",\n    \"servingSize\": 2,\n    \"cookingTime\": 30,\n    \"cuisineType\": \"WESTERN\",\n    \"mealType\": \"MAIN\",\n    \"difficulty\": \"BEGINNER\",\n    \"ingredients\": [\n        {\"name\": \"가지\", \"amount\": \"2\", \"unit\": \"개\"},\n        {\"name\": \"소금\", \"amount\": \"2\", \"unit\": \"꼬집\"},\n        {\"name\": \"올리브오일\", \"amount\": \"1\", \"unit\": \"큰술\"},\n        {\"name\": \"다진 소고기\", \"amount\": \"100\", \"unit\": \"g\"},\n        {\"name\": \"후추\", \"amount\": \"0.1\", \"unit\": \"큰술\"},\n        {\"name\": \"다진 마늘\", \"amount\": \"0.5\", \"unit\": \"큰술\"},\n        {\"name\": \"양파\", \"amount\": \"0.5\", \"unit\": \"개\"},\n        {\"name\": \"토마토 소스\", \"amount\": \"1.5\", \"unit\": \"컵\"},\n        {\"name\": \"알룰로스\", \"amount\": \"1\", \"unit\": \"큰술\"},\n        {\"name\": \"포두부\", \"amount\": \"4\", \"unit\": \"장\"},\n        {\"name\": \"모짜렐라 치즈\", \"amount\": \"100\", \"unit\": \"g\"}\n    ],\n    \"steps\": [\n        {\"stepNumber\": 1, \"description\": \"가지를 얇게 슬라이스하여 마른 팬에 소금을 뿌려 수분이 날아가도록 노릇하게 굽습니다.\"},\n        {\"stepNumber\": 2, \"description\": \"팬에 올리브오일을 두르고 다진 소고기, 소금, 후추를 넣어 볶습니다.\"},\n        {\"stepNumber\": 3, \"description\": \"고기의 핏기가 사라지면 다진 마늘과 다진 양파를 넣고 양파가 투명해질 때까지 볶습니다.\"},\n        {\"stepNumber\": 4, \"description\": \"토마토 소스와 알룰로스를 넣고 골고루 섞으며 끓여 소스를 완성합니다.\"},\n        {\"stepNumber\": 5, \"description\": \"포두부, 구운 가지, 소스, 치즈 순서로 3~4번 반복하여 층을 쌓습니다.\"},\n        {\"stepNumber\": 6, \"description\": \"에어프라이어 180도에서 10~15분간 치즈가 충분히 녹을 때까지 굽습니다.\"}\n    ],\n    \"tags\": [\"라자냐\", \"양식\", \"다이어트식\", \"건강식\"]\n}',
        NULL, NULL, 'COMPLETED', '2026-02-16 03:39:29.065034', '2026-02-16 03:39:57.873697'),
