        '{\n  \"title\": \"닭도리탕\",\n  \"description\": \"매콤하고 진한 양념이 닭고기에 쏙 배어든 닭도리탕입니다. 닭을 미리 데쳐내어 잡내 없이 깔끔한 맛을 냅니다.\",\n  \"servingSize\": 2,\n  \"cookingTime\": 30,\n  \"cuisineType\": \"KOREAN\",\n  \"mealType\": \"MAIN\",\n  \"difficulty\": \"BEGINNER\",\n  \"ingredients\": [\n    {\n      \"name\": \"닭볶음탕용 닭\",\n      \"amount\": \"1\",\n      \"unit\": \"마리\"\n    },\n    {\n      \"name\": \"양파\",\n      \"amount\": \"1\",\n      \"unit\": \"개\"\n    },\n    {\n      \"name\": \"감자\",\n      \"amount\": \"2\",\n      \"unit\": \"개\"\n    },\n    {\n      \"name\": \"대파\",\n      \"amount\": \"1\",\n      \"unit\": \"대\"\n    },\n    {\n      \"name\": \"다진 마늘\",\n      \"amount\": \"3\",\n      \"unit\": \"큰술\"\n    },\n    {\n      \"name\": \"고추장\",\n      \"amount\": \"2\",\n      \"unit\": \"큰술\"\n    },\n    {\n      \"name\": \"고춧가루\",\n      \"amount\": \"3\",\n      \"unit\": \"큰술\"\n    },\n    {\n      \"name\": \"미림\",\n      \"amount\": \"2\",\n      \"unit\": \"큰술\"\n    },\n    {\n      \"name\": \"간장\",\n      \"amount\": \"2\",\n      \"unit\": \"큰술\"\n    },\n    {\n      \"name\": \"설탕\",\n      \"amount\": \"1\",\n      \"unit\": \"큰술\"\n    },\n    {\n      \"name\": \"올리고당\",\n      \"amount\": \"1\",\n      \"unit\": \"큰술\"\n    },\n    {\n      \"name\": \"후추\",\n      \"amount\": \"0.1\",\n      \"unit\": \"큰술\"\n    },\n    {\n      \"name\": \"미원\",\n      \"amount\": \"0.3\",\n      \"unit\": \"작은술\"\n    },\n    {\n      \"name\": \"다시다\",\n      \"amount\": \"0.3\",\n      \"unit\": \"작은술\"\n    },\n    {\n      \"name\": \"물\",\n      \"amount\": \"500\",\n      \"unit\": \"ml\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": 1,\n      \"description\": \"끓는 물에 닭볶음탕용 닭을 넣어 5분 정도 데쳐줍니다.\"\n    },\n    {\n      \"stepNumber\": 2,\n      \"description\": \"데친 닭은 흐르는 물에 씻어 뼛가루와 불순물을 제거합니다.\"\n    },\n    {\n      \"stepNumber\": 3,\n      \"description\": \"다진 마늘, 고추장, 고춧가루, 미림, 간장, 설탕, 올리고당, 후추, 미원, 다시다를 섞어 양념장을 만듭니다.\"\n    },\n    {\n      \"stepNumber\": 4,\n      \"description\": \"냄비에 데친 닭, 채 썬 양파, 깍둑썰기한 감자, 양념장, 물 500ml를 넣고 끓입니다.\"\n    },\n    {\n      \"stepNumber\": 5,\n      \"description\": \"물이 끓어오르면 양념을 잘 풀어준 뒤 뚜껑을 덮고 15분간 끓입니다.\"\n    },\n    {\n      \"stepNumber\": 6,\n      \"description\": \"큼직하게 썬 대파를 넣고 5분 정도 더 익혀 완성합니다.\"\n    }\n  ],\n  \"tags\": [\n    \"한식\",\n    \"메인요리\",\n    \"매콤한맛\",\n    \"밥도둑\"\n  ]\n}',
