        '{\n    \"title\": \"토마토 원팬 파스타\",\n    \"description\": \"팬 하나로 간편하게 조리하여 설거지를 줄인 새우 베이컨 토마토 파스타입니다.\",\n    \"servingSize\": 1,\n    \"cookingTime\": 25,\n    \"cuisineType\": \"WESTERN\",\n    \"mealType\": \"MAIN\",\n    \"difficulty\": \"BEGINNER\",\n    \"ingredients\": [\n        {\n            \"name\": \"새우\",\n            \"amount\": \"6\",\n            \"unit\": \"개\"\n        },\n        {\n            \"name\": \"양파\",\n            \"amount\": \"0.5\",\n            \"unit\": \"개\"\n        },\n        {\n            \"name\": \"베이컨\",\n            \"amount\": \"4\",\n            \"unit\": \"줄\"\n        },\n        {\n            \"name\": \"다진 마늘\",\n            \"amount\": \"1\",\n            \"unit\": \"큰술\"\n        },\n        {\n            \"name\": \"물\",\n            \"amount\": \"500\",\n            \"unit\": \"ml\"\n        },\n        {\n            \"name\": \"토마토 소스\",\n            \"amount\": \"300\",\n            \"unit\": \"g\"\n        },\n        {\n            \"name\": \"스파게티 면\",\n            \"amount\": \"120\",\n            \"unit\": \"g\"\n        }\n    ],\n    \"steps\": [\n        {\n            \"stepNumber\": 1,\n            \"description\": \"양파 1/2개와 베이컨 4줄을 먹기 좋은 크기로 썹니다.\"\n        },\n        {\n            \"stepNumber\": 2,\n            \"description\": \"팬에 다진 마늘 1큰술, 양파, 베이컨, 새우를 넣고 3분간 볶습니다.\"\n        },\n        {\n            \"stepNumber\": 3,\n            \"description\": \"물 500ml를 붓고 스파게티 면 120g을 넣어 12분간 끓입니다.\"\n        },\n        {\n            \"stepNumber\": 4,\n            \"description\": \"토마토 소스 300g(약 반 통)을 넣고 3분간 더 저어가며 졸여 완성합니다.\"\n        }\n    ],\n    \"tags\": [\n        \"양식\",\n        \"원팬요리\",\n        \"자취요리\",\n        \"파스타\"\n    ]\n}',
