        '{\n    \"title\": \"원팬 토마토 파스타\",\n    \"description\": \"냄비 하나로 재료를 모두 넣어 조리하여 설거지가 적고 간편한 토마토 파스타입니다.\",\n    \"servingSize\": 1,\n    \"cookingTime\": 20,\n    \"cuisineType\": \"WESTERN\",\n    \"mealType\": \"MAIN\",\n    \"difficulty\": \"BEGINNER\",\n    \"ingredients\": [\n        {\"name\": \"새우\", \"amount\": \"6\", \"unit\": \"개\"},\n        {\"name\": \"양파\", \"amount\": \"0.5\", \"unit\": \"개\"},\n        {\"name\": \"베이컨\", \"amount\": \"4\", \"unit\": \"줄\"},\n        {\"name\": \"다진 마늘\", \"amount\": \"1\", \"unit\": \"큰술\"},\n        {\"name\": \"물\", \"amount\": \"500\", \"unit\": \"ml\"},\n        {\"name\": \"토마토 소스\", \"amount\": \"300\", \"unit\": \"g\"},\n        {\"name\": \"스파게티 면\", \"amount\": \"120\", \"unit\": \"g\"}\n    ],\n    \"steps\": [\n        {\"stepNumber\": 1, \"description\": \"양파 1/2개와 베이컨 4줄을 먹기 좋은 크기로 썰어 준비합니다.\"},\n        {\"stepNumber\": 2, \"description\": \"팬에 다진 마늘 1큰술, 양파, 베이컨, 새우를 넣고 3분간 볶습니다.\"},\n        {\"stepNumber\": 3, \"description\": \"물 500ml와 스파게티 면 120g을 넣고 12분간 끓입니다.\"},\n        {\"stepNumber\": 4, \"description\": \"토마토 소스 300g을 넣고 3분간 더 저어가며 볶아 완성합니다.\"}\n    ],\n    \"tags\": [\"양식\", \"원팬요리\", \"간단요리\", \"한그릇요리\"]\n}',
