        '{\n    \"title\": \"투움바 파스타\",\n    \"description\": \"생크림 없이 우유와 치즈만으로 꾸덕한 식감을 낸 초간단 원팬 투움바 파스타입니다.\",\n    \"servingSize\": 1,\n    \"cookingTime\": 15,\n    \"cuisineType\": \"WESTERN\",\n    \"mealType\": \"MAIN\",\n    \"difficulty\": \"BEGINNER\",\n    \"ingredients\": [\n        {\"name\": \"통밀 파스타면\", \"amount\": \"100\", \"unit\": \"g\"},\n        {\"name\": \"새우\", \"amount\": \"7\", \"unit\": \"마리\"},\n        {\"name\": \"양파\", \"amount\": \"0.25\", \"unit\": \"개\"},\n        {\"name\": \"양송이버섯\", \"amount\": \"3\", \"unit\": \"개\"},\n        {\"name\": \"베이컨\", \"amount\": \"2\", \"unit\": \"줄\"},\n        {\"name\": \"쪽파\", \"amount\": \"1\", \"unit\": \"대\"},\n        {\"name\": \"슬라이스 치즈\", \"amount\": \"2\", \"unit\": \"장\"},\n        {\"name\": \"다진 마늘\", \"amount\": \"1\", \"unit\": \"큰술\"},\n        {\"name\": \"고춧가루\", \"amount\": \"1\", \"unit\": \"큰술\"},\n        {\"name\": \"저당 케첩\", \"amount\": \"1\", \"unit\": \"큰술\"},\n        {\"name\": \"치킨스톡\", \"amount\": \"0.5\", \"unit\": \"큰술\"},\n        {\"name\": \"버터\", \"amount\": \"10\", \"unit\": \"g\"},\n        {\"name\": \"페페론치노\", \"amount\": \"0.5\", \"unit\": \"큰술\"},\n        {\"name\": \"우유\", \"amount\": \"400\", \"unit\": \"ml\"},\n        {\"name\": \"물\", \"amount\": \"200\", \"unit\": \"ml\"},\n        {\"name\": \"후추\", \"amount\": \"0.1\", \"unit\": \"작은술\"},\n        {\"name\": \"파슬리\", \"amount\": \"0.1\", \"unit\": \"작은술\"}\n    ],\n    \"steps\": [\n        {\"stepNumber\": 1, \"description\": \"팬에 통밀 파스타면, 채 썬 양파, 버섯, 새우, 베이컨, 송송 썬 쪽파를 가지런히 담습니다.\"},\n        {\"stepNumber\": 2, \"description\": \"준비된 재료 위에 슬라이스 치즈, 다진 마늘, 고춧가루, 저당 케첩, 치킨스톡, 버터를 올립니다.\"},\n        {\"stepNumber\": 3, \"description\": \"매콤한 맛을 선호한다면 페페론치노를 추가로 넣습니다.\"},\n        {\"stepNumber\": 4, \"description\": \"물과 우유를 붓고 중불에서 소스가 꾸덕해질 때까지 면을 익히며 저어줍니다.\"},\n        {\"stepNumber\": 5, \"description\": \"소스가 적당히 졸아들면 그릇에 옮겨 담고 후추와 파슬리를 뿌려 완성합니다.\"}\n    ],\n    \"tags\": [\"양식\", \"원팬요리\", \"다이어트식단\", \"파스타\"]\n}',
