       (25, 1, 24, 25, 'https://youtube.com/shorts/OhE8bWuC2mc?si=m-RsDKLUwhVjHXiM', 'YOUTUBE',
        '{\n    \"title\": \"두바이 쫀득쿠키\",\n    \"description\": \"카다이프의 바삭함과 마시멜로우의 쫀득함이 조화로운 이색적인 두바이 스타일 쿠키입니다.\",\n    \"servingSize\": 4,\n    \"cookingTime\": 60,\n    \"cuisineType\": \"FUSION\",\n    \"mealType\": \"SNACK\",\n    \"difficulty\": \"INTERMEDIATE\",\n    \"ingredients\": [\n        {\n            \"name\": \"카다이프\",\n            \"amount\": \"200\",\n            \"unit\": \"g\"\n        },\n        {\n            \"name\": \"녹인 버터\",\n            \"amount\": \"60\",\n            \"unit\": \"g\"\n        },\n        {\n            \"name\": \"피스타치오 스프레드\",\n            \"amount\": \"100\",\n            \"unit\": \"g\"\n        },\n        {\n            \"name\": \"버터\",\n            \"amount\": \"25\",\n            \"unit\": \"g\"\n        },\n        {\n            \"name\": \"마시멜로우\",\n            \"amount\": \"250\",\n            \"unit\": \"g\"\n        },\n        {\n            \"name\": \"코코아 파우더\",\n            \"amount\": \"15\",\n            \"unit\": \"g\"\n        },\n        {\n            \"name\": \"탈지분유\",\n            \"amount\": \"10\",\n            \"unit\": \"g\"\n        }\n    ],\n    \"steps\": [\n        {\n            \"stepNumber\": 1,\n            \"description\": \"카다이프 200g에 녹인 버터 60g을 넣고 고르게 잘 섞어줍니다.\"\n        },\n        {\n            \"stepNumber\": 2,\n            \"description\": \"오븐 팬에 넓게 펴서 180도 예열된 오븐에서 15분간 노릇하게 굽습니다.\"\n        },\n        {\n            \"stepNumber\": 3,\n            \"description\": \"구워진 카다이프에 피스타치오 스프레드를 넣고 잘 버무려 섞습니다.\"\n        },\n        {\n            \"stepNumber\": 4,\n            \"description\": \"냉장고에서 살짝 굳힌 뒤 30g씩 동그랗게 모양을 잡아 냉동실에 얼려둡니다.\"\n        },\n        {\n            \"stepNumber\": 5,\n            \"description\": \"팬에 버터 25g을 약불로 녹인 후 마시멜로우 250g을 넣어 천천히 녹입니다.\"\n        },\n        {\n            \"stepNumber\": 6,\n            \"description\": \"마시멜로우가 다 녹으면 코코아 파우더 15g과 탈지분유 10g을 섞어 반죽을 만듭니다.\"\n        },\n        {\n            \"stepNumber\": 7,\n            \"description\": \"완성된 반죽을 종이호일 위에서 식힌 후 20g씩 소분하여 얼려둔 카다이프 볼을 감쌉니다.\"\n        },\n        {\n            \"stepNumber\": 8,\n            \"description\": \"마지막으로 겉면에 코코아 파우더를 골고루 묻혀 완성합니다.\"\n        }\n    ],\n    \"tags\": [\n        \"두바이쿠키\",\n        \"홈베이킹\",\n        \"디저트\",\n        \"퓨전요리\"\n    ]\n}',
