       (26, 1, 25, 26, 'https://youtube.com/shorts/sn6bI4bSYGw?si=HsFN-UkCen6lD1G9', 'YOUTUBE',
        '{\n    \"title\": \"피스타치오 두쫀쿠\",\n    \"description\": \"마시멜로와 버터 없이 만든 건강하고 쫀득한 식감의 피스타치오 초코 디저트입니다.\",\n    \"servingSize\": 2,\n    \"cookingTime\": 60,\n    \"cuisineType\": \"FUSION\",\n    \"mealType\": \"SNACK\",\n    \"difficulty\": \"INTERMEDIATE\",\n    \"ingredients\": [\n        {\n            \"name\": \"피스타치오\",\n            \"amount\": \"200\",\n            \"unit\": \"g\"\n        },\n        {\n            \"name\": \"알룰로스\",\n            \"amount\": \"6\",\n            \"unit\": \"큰술\"\n        },\n        {\n            \"name\": \"식용유\",\n            \"amount\": \"5\",\n            \"unit\": \"큰술\"\n        },\n        {\n            \"name\": \"소금\",\n            \"amount\": \"2\",\n            \"unit\": \"꼬집\"\n        },\n        {\n            \"name\": \"두유면\",\n            \"amount\": \"3\",\n            \"unit\": \"봉\"\n        },\n        {\n            \"name\": \"타피오카 전분\",\n            \"amount\": \"2\",\n            \"unit\": \"큰술\"\n        },\n        {\n            \"name\": \"우유\",\n            \"amount\": \"7\",\n            \"unit\": \"큰술\"\n        },\n        {\n            \"name\": \"무가당 코코아가루\",\n            \"amount\": \"1\",\n            \"unit\": \"큰술\"\n        }\n    ],\n    \"steps\": [\n        {\n            \"stepNumber\": 1,\n            \"description\": \"피스타치오를 120도 에어프라이어에서 10분간 구운 뒤 믹서기로 곱게 갑니다.\"\n        },\n        {\n            \"stepNumber\": 2,\n            \"description\": \"간 피스타치오에 소금 한 꼬집, 알룰로스 3큰술, 오일 5큰술을 섞어 스프레드를 만듭니다.\"\n        },\n        {\n            \"stepNumber\": 3,\n            \"description\": \"두유면의 물기를 제거하고 160도 에어프라이어에서 8분씩 총 4번 뒤집으며 바삭하게 굽습니다.\"\n        },\n        {\n            \"stepNumber\": 4,\n            \"description\": \"바삭해진 두유면을 부수어 피스타치오 스프레드와 섞은 뒤 동그랗게 빚어 냉장 보관합니다.\"\n        },\n        {\n            \"stepNumber\": 5,\n            \"description\": \"타피오카 전분, 우유, 알룰로스 3큰술, 소금 한 꼬집, 코코아가루 1큰술을 섞습니다.\"\n        },\n        {\n            \"stepNumber\": 6,\n            \"description\": \"반죽을 전자레인지에 1분간 돌려 쫀득하게 만든 뒤 냉장고에서 20분간 식힙니다.\"\n        },\n        {\n            \"stepNumber\": 7,\n            \"description\": \"식힌 반죽을 얇게 펴서 미리 만들어둔 피스타치오 볼을 감싸줍니다.\"\n        },\n        {\n            \"stepNumber\": 8,\n            \"description\": \"겉면에 코코아가루를 골고루 묻혀 마무리합니다.\"\n        }\n    ],\n    \"tags\": [\n        \"디저트\",\n        \"다이어트간식\",\n        \"수제초콜릿\",\n        \"퓨전\"\n    ]\n}',
